  private boolean left,right,jump,jumpPrev,dash,attack,ground,wasGround;
  private int score,lives=3,level=1,tools,coffee,parts,combo;
  private final RectF bL=new RectF(18,424,142,524),bR=new RectF(150,424,274,524),bA=new RectF(502,418,638,524),bD=new RectF(646,418,790,524),bJ=new RectF(800,410,948,524);
  WorkshopRunV5View(Context c,GateCraftGame owner){super(c,owner);restart();}
